// useLiveVideoProcessor.ts (sketch)
export function useLiveVideoProcessor(opts: { enabled: boolean; resolution: {w:number; h:number}; bitrate?: number; }) {
  // placeholder hook sketch: starts/stops native stream and exposes latest frame
  const [frame, setFrame] = React.useState<any>(null)
  React.useEffect(() => {
    if (!opts.enabled) return
    // Native module would provide a frame stream; here we poll for simplicity
    const id = setInterval(() => {
      const f = NativeVideoFrameStreamer.popFrame()
      if (f) setFrame(f)
    }, 16)
    return () => clearInterval(id)
  }, [opts.enabled, opts.resolution, opts.bitrate])
  return { frame, status: 'running' }
}
```

